using UnityEngine;

public class CrystalCounter : MonoBehaviour
{
    [Min(1)] public int target = 3;
    private int count = 0;

    void OnGUI()
    {
        var text = new GUIStyle(GUI.skin.label);
        text.fontSize = 22;
        var button = new GUIStyle(GUI.skin.button);
        button.fontSize = 20;

        GUILayout.BeginArea(
            new Rect(24, 24, 320, 280));
        GUILayout.Label("Собрано: " + count +
            " из " + target, text);

        GUI.enabled = count < target;
        if (GUILayout.Button("Добавить предмет",
            button, GUILayout.Height(52)))
        {
            count++;
        }
        GUI.enabled = true;

        if (count >= target)
            GUILayout.Label("Цель достигнута", text);

        if (GUILayout.Button("Начать заново",
            button, GUILayout.Height(52)))
        {
            count = 0;
        }
        GUILayout.EndArea();
    }
}
